    {"name": "edit", "path": "src/queue.js", "range": "1tx-81wi", "new": "// The queue. README.md has the contract.\n\nimport { CancelledError, TaskTimeoutError } from './errors.js';\n\nexport class JobQueue {\n  constructor({ concurrency = 1 } = {}) {\n    this._validateConcurrency(concurrency);\n    this._concurrency = concurrency;\n    this._running = 0;\n    this._waiting = [];\n    this._paused = false;\n    this._idle = [];\n  }\n\n  _validateConcurrency(value) {\n    if (!Number.isInteger(value) || value <= 0) throw new RangeError('concurrency must be a positive integer');\n  }\n\n  get concurrency() { return this._concurrency; }\n  set concurrency(value) { this._validateConcurrency(value); this._concurrency = value; this._next(); }\n  get pending() { return this._running; }\n  get size() { return this._waiting.length; }\n  get isPaused() { return this._paused; }\n\n  add(fn, { priority = 0, timeout = 0, retries = 0, retryDelay = 0 } = {}) {\n    return new Promise((resolve, reject) => {\n      const job = { fn, priority, timeout, retries, retryDelay, resolve, reject };\n      let index = this._waiting.findIndex((other) => other.priority < priority);\n      if (index < 0) index = this._waiting.length;\n      this._waiting.splice(index, 0, job);\n      this._next();\n    });\n  }\n\n  _next() {\n    if (this._paused || this._running >= this._concurrency) return;\n    const job = this._waiting.shift();\n    if (!job) {\n      if (this._running === 0) for (const resolve of this._idle.splice(0)) resolve();\n      return;\n    }\n    this._running++;\n    this._run(job, 1).then(job.resolve, job.reject).finally(() => { this._running--; this._next(); });\n  }\n\n  async _run(job, attempt) {\n    const controller = new AbortController();\n    let timer;\n    try {\n      const result = Promise.resolve().then(() => job.fn({ signal: controller.signal, attempt }));\n      if (job.timeout > 0) {\n        const timeout = new Promise((_, reject) => {\n          timer = setTimeout(() => { controller.abort(); reject(new TaskTimeoutError(job.timeout)); }, job.timeout);\n        });\n        return await Promise.race([result, timeout]);\n      }\n      return await result;\n    } catch (error) {\n      if (attempt <= job.retries) {\n        if (job.retryDelay > 0) await new Promise((resolve) => setTimeout(resolve, job.retryDelay));\n        return this._run(job, attempt + 1);\n      }\n      throw error;\n    } finally { if (timer) clearTimeout(timer); }\n  }\n\n  pause() { this._paused = true; }\n  resume() { this._paused = false; this._next(); }\n  clear() {\n    const jobs = this._waiting.splice(0);\n    for (const job of jobs) job.reject(new CancelledError());\n    return jobs.length;\n  }\n  onIdle() {\n    if (this._running === 0 && this._waiting.length === 0) return Promise.resolve();\n    return new Promise((resolve) => this._idle.push(resolve));\n  }\n}"},
